from AlgorithmImports import *
import math


class DualStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # SMA period for Strategy A's SPY crossover (not specified explicitly; using 50-day)
        self.sma_period = 50
        self.sma = self.SMA(self.spy, self.sma_period, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

        self.strategyA_shares = 0
        self.strategyB_shares = 0

    def OnData(self, slice):
        for symbol in self.symbols:
            if not slice.Bars.ContainsKey(symbol):
                return

        spy_bar = slice.Bars[self.spy]
        aapl_bar = slice.Bars[self.aapl]

        self._process_strategy_a(spy_bar.Close)
        self._process_strategy_b(aapl_bar.Close)

    def _process_strategy_a(self, price):
        if not self.sma.IsReady:
            return

        sma_val = self.sma.Current.Value

        if self.spy_prev_close is not None and self.spy_prev_sma is not None:
            crossed_above = self.spy_prev_close <= self.spy_prev_sma and price > sma_val
            crossed_below = self.spy_prev_close >= self.spy_prev_sma and price < sma_val

            if self.strategyA_shares > 0:
                if crossed_below:
                    self.MarketOrder(self.spy, -self.strategyA_shares)
                    self.strategyA_shares = 0
            else:
                if crossed_above:
                    target_value = self.Portfolio.TotalPortfolioValue * 0.40
                    shares = math.floor(target_value / price)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.strategyA_shares = shares

        self.spy_prev_close = price
        self.spy_prev_sma = sma_val

    def _process_strategy_b(self, price):
        if self.aapl_prev_close is not None:
            if price < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            if self.strategyB_shares > 0:
                if self.rsi.IsReady and self.rsi.Current.Value > 60:
                    self.MarketOrder(self.aapl, -self.strategyB_shares)
                    self.strategyB_shares = 0
            else:
                if self.aapl_red_streak >= 3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        shares = math.floor(20000 / price)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)
                            self.strategyB_shares = shares

        self.aapl_prev_close = price
