from AlgorithmImports import *


class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]
        self.all_symbols = list(self.symbols.values())

        self.spy_sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_spy_sma = None

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

        self.lotA_shares = 0
        self.lotB_shares = 0

    def OnData(self, data: Slice):
        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol) or data.Bars[symbol] is None:
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        else:
            self.aapl_red_streak = 0

        # Slot 1 - Strategy A (SPY): sell before buy
        if self.spy_sma.IsReady:
            spy_sma_value = self.spy_sma.Current.Value

            if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                if self.lotA_shares > 0:
                    crosses_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < spy_sma_value)
                    if crosses_below:
                        self.MarketOrder(self.spy, -self.lotA_shares)
                        self.lotA_shares = 0
                else:
                    crosses_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma_value)
                    if crosses_above:
                        target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                        shares = int(target_value / spy_close)
                        if shares > 0:
                            self.MarketOrder(self.spy, shares)
                            self.lotA_shares += shares

            self.prev_spy_close = spy_close
            self.prev_spy_sma = spy_sma_value
        else:
            self.prev_spy_close = spy_close
            self.prev_spy_sma = None

        # Slot 2 - Strategy B (AAPL): sell before buy
        if self.aapl_rsi.IsReady:
            rsi_value = self.aapl_rsi.Current.Value

            if self.lotB_shares > 0:
                if rsi_value > 60:
                    self.MarketOrder(self.aapl, -self.lotB_shares)
                    self.lotB_shares = 0
            else:
                if self.aapl_red_streak >= 3:
                    cash_available = self.Portfolio.Cash
                    if cash_available >= 20000:
                        shares = int(20000 / aapl_close)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)
                            self.lotB_shares += shares

        self.aapl_prev_close = aapl_close
