        aapl_close = data.Bars[self.aapl].Close
        sma_value = self.sma.Current.Value
        rsi_value = self.rsi.Current.Value

        # Market-state quantities are always updated, regardless of any lot state.
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Slot 1 - Strategy A (SPY): sell reason checked before buy reason.
        spy_qty = self.Portfolio[self.spy].Quantity
        if self.prev_spy_close is not None and self.prev_sma is not None:
            if spy_qty != 0:
                crosses_below = (self.prev_spy_close >= self.prev_sma) and (spy_close < sma_value)
                if crosses_below:
                    self.Liquidate(self.spy)
            else:
                crosses_above = (self.prev_spy_close <= self.prev_sma) and (spy_close > sma_value)
                if crosses_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    qty = math.floor(target_value / spy_close)
                    if qty > 0:
                        self.MarketOrder(self.spy, qty)

        # Slot 2 - Strategy B (AAPL): sell reason checked before buy reason.
        aapl_qty = self.Portfolio[self.aapl].Quantity
        if aapl_qty != 0:
            if rsi_value > 60:
                self.Liquidate(self.aapl)
        else:
            if self.aapl_red_streak >= 3:
