from AlgorithmImports import *


class DualStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in tickers:
            equity = self.AddEquity(t, Resolution.Daily)
            self.symbols[t] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators used by the rules
        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Manual state for cross detection (Strategy A)
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Manual state for red-streak detection (Strategy B)
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        # Skip the entire day's rule evaluation if any subscribed ticker's bar is missing
        for sym in self.symbols.values():
            if not data.ContainsKey(sym) or data[sym] is None:
                return

