from AlgorithmImports import *
import math


class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # SMA period not specified by the spec; using 50 as a standard trend-following default
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.prev_spy_close = None
        self.prev_spy_sma = None

        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        self.lot_a_shares = 0
        self.lot_b_shares = 0

        self.spy_invest_pct = 0.40
        self.aapl_buy_amount = 20000.0

    def OnData(self, data: Slice):
        spy_has_data = data.Bars.ContainsKey(self.spy)
        aapl_has_data = data.Bars.ContainsKey(self.aapl)

        spy_cross_up = False
        spy_cross_down = False
        if spy_has_data and self.spy_sma.IsReady and self.prev_spy_close is not None and self.prev_spy_sma is not None:
            today_spy_close = data.Bars[self.spy].Close
            today_spy_sma = self.spy_sma.Current.Value
            spy_cross_up = (self.prev_spy_close <= self.prev_spy_sma) and (today_spy_close > today_spy_sma)
            spy_cross_down = (self.prev_spy_close >= self.prev_spy_sma) and (today_spy_close < today_spy_sma)

        if aapl_has_data and self.prev_aapl_close is not None:
            today_aapl_close = data.Bars[self.aapl].Close
            if today_aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        aapl_rsi_sell_signal = aapl_has_data and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60

        universe_ok = all(data.Bars.ContainsKey(s) for s in self.all_symbols)

        if universe_ok:
            # sells before buys
            if self.lot_a_shares > 0 and spy_cross_down:
                self._liquidate_lot_a()

            if self.lot_b_shares > 0 and aapl_rsi_sell_signal:
                self._liquidate_lot_b()

            if self.lot_a_shares == 0 and spy_cross_up:
                self._buy_lot_a(data.Bars[self.spy].Close)

            if self.lot_b_shares == 0 and self.aapl_red_streak >= 3:
                self._buy_lot_b(data.Bars[self.aapl].Close)

        if spy_has_data:
            self.prev_spy_close = data.Bars[self.spy].Close
            if self.spy_sma.IsReady:
                self.prev_spy_sma = self.spy_sma.Current.Value

        if aapl_has_data:
            self.prev_aapl_close = data.Bars[self.aapl].Close

    def _buy_lot_a(self, price):
        target_value = self.Portfolio.TotalPortfolioValue * self.spy_invest_pct
        quantity = math.floor(target_value / price)
        if quantity > 0:
            self.MarketOrder(self.spy, quantity)
            self.lot_a_shares += quantity

    def _liquidate_lot_a(self):
        if self.lot_a_shares > 0:
            self.MarketOrder(self.spy, -self.lot_a_shares)
            self.lot_a_shares = 0

    def _buy_lot_b(self, price):
        if self.Portfolio.Cash >= self.aapl_buy_amount:
            quantity = math.floor(self.aapl_buy_amount / price)
            if quantity > 0:
                self.MarketOrder(self.aapl, quantity)
                self.lot_b_shares += quantity

    def _liquidate_lot_b(self):
        if self.lot_b_shares > 0:
            self.MarketOrder(self.aapl, -self.lot_b_shares)
            self.lot_b_shares = 0
