class MultiSlotIndependentStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)
        self.aapl_prev_closes = RollingWindow[float](3)

    def OnData(self, data: Slice):
        for symbol in self.all_symbols:
            if symbol not in data.Bars:
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        self.HandleStrategyA(spy_close)
        self.HandleStrategyB(aapl_close)

    def HandleStrategyA(self, spy_close):
        if self.sma.IsReady and self.spy_prev_sma is not None:
            sma_value = self.sma.Current.Value
            qty = self.Portfolio[self.spy].Quantity

            crossed_below = self.spy_prev_close >= self.spy_prev_sma and spy_close < sma_value
            crossed_above = self.spy_prev_close <= self.spy_prev_sma and spy_close > sma_value

            if qty > 0 and crossed_below:
                self.Liquidate(self.spy)
            elif qty == 0 and crossed_above:
                target_amount = 0.4 * self.Portfolio.TotalPortfolioValue
                shares = int(target_amount // spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)

        self.spy_prev_close = spy_close
        if self.sma.IsReady:
            self.spy_prev_sma = self.sma.Current.Value

    def HandleStrategyB(self, aapl_close):
        qty = self.Portfolio[self.aapl].Quantity

        if qty > 0:
            if self.rsi.IsReady and self.rsi.Current.Value > 60:
                self.Liquidate(self.aapl)
        elif qty == 0:
            if self.aapl_prev_closes.IsReady:
                d1 = self.aapl_prev_closes[0]
                d2 = self.aapl_prev_closes[1]
                d3 = self.aapl_prev_closes[2]
                red3 = aapl_close < d1 and d1 < d2 and d2 < d3
                if red3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        shares = int(20000 // aapl_close)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)

        self.aapl_prev_closes.Add(aapl_close)
