from AlgorithmImports import *


class RaceGatedStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilder, Resolution.Daily)

        self.aapl_close_window = RollingWindow[float](4)

        self.prev_spy_close = None
        self.prev_spy_sma = None

        self.spy_cross_above = False
        self.spy_cross_below = False
        self.aapl_red_streak_3 = False

        self.lot_a_shares = 0
        self.lot_b_shares = 0

    def OnData(self, data: Slice):
        self._update_spy_state(data)
        self._update_aapl_state(data)

        for symbol in self.symbols:
            if not data.ContainsKey(symbol) or data[symbol] is None:
                return

        # Sells before buys, per template rules
        self._strategy_a_sell(data)
        self._strategy_b_sell(data)
        self._strategy_a_buy(data)
        self._strategy_b_buy(data)

    def _update_spy_state(self, data):
        self.spy_cross_above = False
        self.spy_cross_below = False
        if data.ContainsKey(self.spy) and data[self.spy] is not None and self.sma.IsReady:
            close = data[self.spy].Close
            sma_value = self.sma.Current.Value
            if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                if self.prev_spy_close <= self.prev_spy_sma and close > sma_value:
                    self.spy_cross_above = True
                if self.prev_spy_close >= self.prev_spy_sma and close < sma_value:
                    self.spy_cross_below = True
            self.prev_spy_close = close
            self.prev_spy_sma = sma_value

    def _update_aapl_state(self, data):
        self.aapl_red_streak_3 = False
        if data.ContainsKey(self.aapl) and data[self.aapl] is not None:
            close = data[self.aapl].Close
            self.aapl_close_window.Add(close)
            if self.aapl_close_window.Count == 4:
                c0 = self.aapl_close_window[0]
                c1 = self.aapl_close_window[1]
                c2 = self.aapl_close_window[2]
                c3 = self.aapl_close_window[3]
                if c0 < c1 and c1 < c2 and c2 < c3:
                    self.aapl_red_streak_3 = True

    def _strategy_a_sell(self, data):
        if self.lot_a_shares > 0 and self.spy_cross_below:
            self.MarketOrder(self.spy, -self.lot_a_shares)

    def _strategy_a_buy(self, data):
        if self.lot_a_shares == 0 and self.sma.IsReady and self.spy_cross_above:
            price = data[self.spy].Close
            target_value = 0.4 * self.Portfolio.TotalPortfolioValue
            quantity = int(target_value // price)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)

    def _strategy_b_sell(self, data):
        if self.lot_b_shares > 0 and self.rsi.IsReady and self.rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.lot_b_shares)

    def _strategy_b_buy(self, data):
        if self.lot_b_shares == 0 and self.aapl_red_streak_3:
            cash_available = self.Portfolio.Cash
            if cash_available >= 20000:
                price = data[self.aapl].Close
                quantity = int(20000 // price)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status != OrderStatus.Filled and orderEvent.Status != OrderStatus.PartiallyFilled:
            return
        if orderEvent.Symbol == self.spy:
            self.lot_a_shares += orderEvent.FillQuantity
        elif orderEvent.Symbol == self.aapl:
            self.lot_b_shares += orderEvent.FillQuantity
